std::complex<float> cf{1.0f};
std::complex<double> cd{2.0};
long double ld = 3.0L;

// Resolution Rule: Argument type T determined by highest precision.
// Function call resolves to T std::tanh(std::complex<T> arg).

// A: scalar float promoted to complex<float>
auto res_A = std::tanh(cf + 5.0f);    // res_A is complex<float>

// B: scalar int promoted to complex<double>
auto res_B = std::tanh(cd + 4);       // res_B is complex<double>

// C: highest precision wins (long double > double)
//    cd promoted to complex<long double>
auto res_C = std::tanh(ld + cd);      // res_C is complex<long double>
